def barycentric_closest(pt,tri):
 # Recompute a bounded point ON the chosen triangle; BVH float32 closest
 # output can yield small negative weights (r93), never treat those as valid.
 a,b=tri[1]-tri[0],tri[2]-tri[0];scale=max(np.linalg.norm(a),np.linalg.norm(b));u=np.linalg.lstsq(np.column_stack((a/scale,b/scale)),(pt-tri[0])/scale,rcond=None)[0];w=np.r_[1-u.sum(),u];w=np.maximum(w,0);return w/w.sum()
